export async function registerHealth(app: FastifyInstance, deps: { db: unknown }): Promise<void> {
  // liveness: NAO toca dependencia externa
  app.get("/health", async () => ({ status: "ok", uptime: process.uptime() }));

  // readiness: checa dependencia real
  app.get("/ready", async (_request, reply) => {
    const checks: Record<string, "ok" | "fail"> = { database: "ok", cache: "ok" };
    let ready = true;
    try {
      await (deps.db as { $queryRaw: (q: string) => Promise<unknown> }).$queryRaw("SELECT 1");
    } catch {
      checks["database"] = "fail";
      ready = false;
    }
    if (!ready) return reply.code(503).send({ status: "not_ready", checks });
    return reply.send({ status: "ready", checks });
  });
}

export function registerShutdown(app: FastifyInstance, deps: { closeDb: () => Promise<void> }): void {
  let closing = false;
  const shutdown = async (signal: string) => {
    if (closing) return;
    closing = true;
    app.log.info({ signal }, "encerrando");

    const timer = setTimeout(() => { app.log.error("timeout no shutdown"); process.exit(1); }, 10_000);
    timer.unref();

    try {
      await app.close();
      await deps.closeDb();
      clearTimeout(timer);
      process.exit(0);
    } catch (error) {
      app.log.error({ error }, "falha no shutdown");
      process.exit(1);
    }
  };
  process.on("SIGTERM", () => void shutdown("SIGTERM"));
  process.on("SIGINT", () => void shutdown("SIGINT"));
}
